154	@@ -0,0 +1,75 @@
155	+/* ============================ Lái xe: camera sau xe ============================
156	+   Camera sau xe `cam.dist`, cao `cam.height` trên mặt đường dưới xe, nhìn vào điểm trước tâm xe `lookAhead`, cao `look` (spec §3 mục 4).
157	+   - Hướng camera bám hướng THÂN xe (không theo vận tốc) với trễ `lag`: lùi xe thì camera vẫn ở sau đuôi, không quay ra trước.
158	+     Vị trí bám thẳng tâm xe (không trễ), để ở 100 km/h camera không tụt xa.
159	+   - Người chơi kéo chuột thêm lệch yaw / pitch (DrCam); thôi kéo `returnAfter` giây thì lệch về 0 theo `returnRate`.
160	+   - Xe trong ô 'tunnel' (cả đoạn hở) thì khoảng lùi `tunnelDist`, độ cao `tunnelHeight`; độ cao kẹp dưới trần ống (hrRoadY + hanTunnel.clear − roof)
161	+     khi xe hoặc camera ở trong ô hầm (drSegClear không biết trần hầm nên kẹp ở đây).
162	+   - Đoạn từ điểm nhìn trên xe tới chỗ camera muốn đứng vướng vật cản (drSegClear < 1): kéo gần (lùi thêm `gap`, không dưới `minDist`)
163	+     và hạ về `tunnelHeight`. Khoảng lùi co lại ngay, nở ra theo `lag` (không giật khi vừa thoát góc tường); độ cao đổi mượt theo `lag`.
164	+   - Không thấp hơn mặt đường tại chỗ camera + `floor` (không có mặt đường cùng tầng thì so với mặt đường dưới xe).
165	+   Gầm cầu (đường ven sông chui dưới dốc Trần Thị Lý) chưa kiểm: vật cản không có mặt cầu. Không cấp phát (D-018). */
166	+import type * as THREE from 'three';
167	+import { CONFIG } from '../../config';
168	+import { HR, hrRoadY } from '../../bridges/han-tunnel/profile';
169	+import { drGround, type DrNet } from './net';
170	+import { drSegClear } from './collide';
171	+import type { DrState } from './motion';
172	+
173	+export interface DrCam { yaw: number; pitch: number; idle: number }   // yaw, pitch: lệch do người chơi kéo (rad); idle: giây từ lần kéo cuối
174	+
175	+const DR_TUNNEL_DY = 2;                       // m — ô hầm chứa (x, z) được tính khi mặt đường ô lệch cao độ tham chiếu không quá chừng này (đường ven sông chạy trên hầm cách ≥ 10 m)
176	+const cs = { ok: false, head: 0, dist: 0, height: 0 };   // hướng đã trễ, khoảng lùi và độ cao đang dùng
177	+const TAU = Math.PI * 2;
178	+const wrap = (a: number): number => a - TAU * Math.round(a / TAU);
179	+
180	+/* (x, z) nằm trong ô 'tunnel' gần cao độ y không (duyệt tuyến tính, không cấp phát) */
181	+function drInTunnel(net: DrNet, x: number, z: number, y: number): boolean {
182	+  const pads = net.pads;
183	+  for (let i = 0; i < pads.length; i++) {
184	+    const p = pads[i];
185	+    if (p.kind !== 'tunnel' || x < p.x0 || x > p.x1 || z < p.z0 || z > p.z1) continue;
186	+    if (Math.abs(p.y(x, z) - y) <= DR_TUNNEL_DY) return true;
187	+  }
188	+  return false;
189	+}
190	+
191	+export function drCamPlace(camera: THREE.PerspectiveCamera, s: DrState, c: DrCam, net: DrNet, dt: number, snap?: boolean): void {
192	+  const K = CONFIG.drive.cam;
193	+  /* 1) lệch do kéo tự về sau returnAfter giây */
194	+  if (!snap && dt > 0) {
195	+    c.idle += dt;
196	+    if (c.idle > K.returnAfter) { const k = Math.exp(-K.returnRate * dt); c.yaw *= k; c.pitch *= k; }
197	+  }
198	+  /* 2) hướng bám thân xe, có trễ */
199	+  const tun = drInTunnel(net, s.x, s.z, s.y);
200	+  let dist = tun ? K.tunnelDist : K.dist, height = tun ? K.tunnelHeight : K.height;
201	+  const first = snap || !cs.ok || !(dt > 0), k = first ? 1 : 1 - Math.exp(-K.lag * dt);
202	+  if (first) { cs.head = s.yaw; cs.ok = true; } else cs.head = wrap(cs.head + wrap(s.yaw - cs.head) * k);
203	+  /* 3) chỗ camera muốn đứng, cắt theo vật cản từ điểm nhìn trên xe */
204	+  const yaw = cs.head + c.yaw, cp = Math.cos(c.pitch), sp = Math.sin(c.pitch), fx = Math.cos(yaw), fz = -Math.sin(yaw);
205	+  const ay = s.y + K.look;
206	+  const t = drSegClear(net, s.x, ay, s.z, s.x - fx * dist * cp, s.y + height + dist * sp, s.z - fz * dist * cp);
207	+  if (t < 1) { const d = dist * t - K.gap; dist = d > K.minDist ? d : K.minDist; if (height > K.tunnelHeight) height = K.tunnelHeight; }
208	+  if (first || dist < cs.dist) cs.dist = dist; else cs.dist += (dist - cs.dist) * k;
209	+  if (first) cs.height = height; else cs.height += (height - cs.height) * k;
210	+  const cx = s.x - fx * cs.dist * cp, cz = s.z - fz * cs.dist * cp;
211	+  let cy = s.y + cs.height + cs.dist * sp;
212	+  /* 4) dưới trần ống hầm (xe hoặc camera trong ô hầm) */
213	+  if (tun || drInTunnel(net, cx, cz, s.y)) { const roof = hrRoadY(cx) + HR.clear - K.roof; if (cy > roof) cy = roof; }
214	+  /* 5) trên mặt đường tại chỗ camera */
215	+  const g = drGround(net, cx, cz, s.y), floor = (g === g ? g : s.y) + K.floor;
216	+  if (cy < floor) cy = floor;
217	+  camera.position.set(cx, cy, cz);
218	+  const hx = Math.cos(s.yaw), hz = -Math.sin(s.yaw);
219	+  camera.lookAt(s.x + hx * K.lookAhead, ay, s.z + hz * K.lookAhead);
220	+}
221	+
222	+/* Kéo chuột: sang phải quay camera sang phải (yaw giảm), kéo xuống nâng camera nhìn xuống (pitch tăng); đặt lại đồng hồ tự về */
223	+export function drCamDrag(c: DrCam, dxPx: number, dyPx: number): void {
224	+  const K = CONFIG.drive.cam;
225	+  c.yaw = wrap(c.yaw - dxPx * K.mouse);   // trong ±π: tự về theo đường ngắn nhất
226	+  c.pitch += dyPx * K.mouse;
227	+  if (c.pitch < K.pitchMin) c.pitch = K.pitchMin; else if (c.pitch > K.pitchMax) c.pitch = K.pitchMax;
228	+  c.idle = 0;
229	+}
